<?php
require_once __DIR__.'/../includes/config.php';
require_once __DIR__.'/../includes/session.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['rider_id'])){header('Location:rider-login.php');exit;}
$rid=(int)$_SESSION['rider_id'];
function eh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$conn->query("CREATE TABLE IF NOT EXISTS rider_payouts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('pending','approved','paid','cancelled') NOT NULL DEFAULT 'pending',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(rider_id,status),INDEX(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
/* Repair payout records for deliveries completed before the payout trigger was installed. */
$base=80.00;$q=$conn->query("SELECT setting_value FROM business_settings WHERE setting_key='rider_base_payout' LIMIT 1");if($q&&($x=$q->fetch_assoc()))$base=(float)$x['setting_value'];
$s=$conn->prepare("INSERT INTO rider_payouts(rider_id,order_id,amount,status,created_at) SELECT rd.rider_id,rd.order_id,?,'pending',COALESCE(rd.delivered_at,NOW()) FROM rider_deliveries rd LEFT JOIN rider_payouts rp ON rp.rider_id=rd.rider_id AND rp.order_id=rd.order_id WHERE rd.rider_id=? AND LOWER(COALESCE(rd.status,''))='delivered' AND rp.id IS NULL");if($s){$s->bind_param('di',$base,$rid);$s->execute();$s->close();}
$completed=0;$earned=0;$pending=0;$paid=0;$history=[];
$sql="SELECT rp.id,rp.order_id,rp.amount,rp.status,rp.created_at,rp.paid_at,o.order_number,r.name restaurant_name FROM rider_payouts rp LEFT JOIN orders o ON o.id=rp.order_id LEFT JOIN restaurants r ON r.id=o.restaurant_id WHERE rp.rider_id=? ORDER BY rp.id DESC";$st=$conn->prepare($sql);if($st){$st->bind_param('i',$rid);$st->execute();$rs=$st->get_result();while($x=$rs->fetch_assoc()){$history[]=$x;$completed++;$amt=(float)$x['amount'];if($x['status']!=='cancelled')$earned+=$amt;if($x['status']==='pending'||$x['status']==='approved')$pending+=$amt;if($x['status']==='paid')$paid+=$amt;}$st->close();}
$today=0;$month=0;foreach($history as $x){if($x['status']==='cancelled')continue;$d=strtotime($x['created_at']);if(date('Y-m-d',$d)===date('Y-m-d'))$today+=(float)$x['amount'];if(date('Y-m',$d)===date('Y-m'))$month+=(float)$x['amount'];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Earnings | Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f9;font:14px Segoe UI,Arial;color:#222}.page{margin-left:223px;padding:32px;max-width:1200px}h1{margin:0;font-size:32px}.sub{color:#777}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:15px;margin:25px 0}.stat{background:#fff;border:1px solid #eee;border-radius:15px;padding:18px}.stat i{color:#ed0038;float:right}.stat small{color:#888}.stat b{display:block;font-size:23px;margin-top:7px}.card{background:#fff;border:1px solid #eee;border-radius:16px;padding:20px}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:13px;border-bottom:1px solid #eee}.table th{font-size:12px;color:#888}.badge{display:inline-block;padding:6px 10px;border-radius:20px;font-size:11px;font-weight:800;background:#fff1dc;color:#8a5a00}.paid{background:#eaf9ef;color:#176c36}.approved{background:#eaf6ff;color:#086d9e}.cancelled{background:#f1f1f1;color:#777}@media(max-width:1050px){.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.page{margin-left:0;padding:20px}.stats{grid-template-columns:1fr 1fr}.table{display:block;overflow:auto;white-space:nowrap}}@media(max-width:500px){.stats{grid-template-columns:1fr}}</style></head><body><?php include __DIR__.'/rider-sidebar.php';?><main class="page"><h1>Earnings</h1><p class="sub">Your per-order delivery earnings and payout status.</p><div class="stats"><div class="stat"><i class="fa-solid fa-calendar-day"></i><small>Today</small><b>Rs <?=number_format($today,0)?></b></div><div class="stat"><i class="fa-solid fa-calendar"></i><small>This Month</small><b>Rs <?=number_format($month,0)?></b></div><div class="stat"><i class="fa-solid fa-wallet"></i><small>Total Earned</small><b>Rs <?=number_format($earned,0)?></b></div><div class="stat"><i class="fa-solid fa-clock"></i><small>Pending Payout</small><b>Rs <?=number_format($pending,0)?></b></div><div class="stat"><i class="fa-solid fa-circle-check"></i><small>Paid Out</small><b>Rs <?=number_format($paid,0)?></b></div></div><div class="card"><h2>Per-Order Earnings</h2><?php if(!$history):?><p style="color:#888;text-align:center;padding:35px">No completed delivery payouts yet.</p><?php else:?><table class="table"><tr><th>Order</th><th>Restaurant</th><th>Earned</th><th>Status</th><th>Created</th><th>Paid At</th></tr><?php foreach($history as $x):?><tr><td>#<?=eh($x['order_number']?:$x['order_id'])?></td><td><?=eh($x['restaurant_name']?:'Restaurant')?></td><td><b>Rs <?=number_format((float)$x['amount'],2)?></b></td><td><span class="badge <?=eh($x['status'])?>"><?=eh(ucfirst($x['status']))?></span></td><td><?=eh(date('d M Y, h:i A',strtotime($x['created_at'])))?></td><td><?=eh($x['paid_at']?date('d M Y, h:i A',strtotime($x['paid_at'])):'—')?></td></tr><?php endforeach;?></table><?php endif;?></div></main></body></html>